import networkx as nx
import itertools

edges = [(1,5), (0,1), (1,3), (3,6), (2,8), (4,5), (4,6)]
G = nx.Graph()
G.add_nodes_from(range(9))
G.add_edges_from(edges)

import z3

X = {}
for i in range(9):
    for j in range(i+1, 9):
        X[(i,j)] = z3.Bool(f"e_{i}_{j}")

s = z3.Solver()

# Known edges
for i in range(9):
    for j in range(i+1, 9):
        if G.has_edge(i, j):
            s.add(X[(i,j)] == True)

# Min degree >= 4
for i in range(9):
    deg_i = []
    for j in range(9):
        if i < j:
            deg_i.append(z3.If(X[(i,j)], 1, 0))
        elif i > j:
            deg_i.append(z3.If(X[(j,i)], 1, 0))
    s.add(z3.Sum(deg_i) >= 4)

# Minimize number of edges
total_edges = z3.Sum([z3.If(X[(i,j)], 1, 0) for i in range(9) for j in range(i+1, 9)])
# We can just find any model, but let's try to find one with exactly 18 edges
s.add(total_edges == 18)

if s.check() == z3.sat:
    m = s.model()
    res = []
    for i in range(9):
        for j in range(i+1, 9):
            if z3.is_true(m[X[(i,j)]]):
                res.extend([i, j])
    print("SAT")
    print(res)
else:
    print("UNSAT")

