G.add_nodes_from(range(9))
G.add_edges_from(edges)

all_possible_edges = list(itertools.combinations(range(9), 2))
remaining_edges = [e for e in all_possible_edges if not G.has_edge(*e)]

from pysat.solvers import Glucose3

solver = Glucose3()

# Variables for edges
edge_vars = {}
var_idx = 1
for i in range(9):
    for j in range(i+1, 9):
        edge_vars[(i,j)] = var_idx
        var_idx += 1

# Known edges
for i in range(9):
    for j in range(i+1, 9):
        if G.has_edge(i, j):
            solver.add_clause([edge_vars[(i,j)]])

# Min degree >= 4
from pysat.card import CardEnc

for i in range(9):
    incident_edges = []
    for j in range(9):
        if i < j:
            incident_edges.append(edge_vars[(i,j)])
        elif i > j:
            incident_edges.append(edge_vars[(j,i)])

    # sum(incident_edges) >= 4
    # which means sum(~incident_edges) <= len(incident_edges) - 4
    # len(incident_edges) is 8. So sum(~incident_edges) <= 4
    neg_incident = [-v for v in incident_edges]
    cnf = CardEnc.atmost(lits=neg_incident, bound=4, vpool=None)
    for clause in cnf.clauses:
        solver.add_clause(clause)

